'use client';
import { useState } from 'react';
import Image from 'next/image';
import { adminRequest, enc, record, rows, text, type EventSummary } from '@/lib/admin';
import { Details, EditorDialog, LoadState, Table, useAdminData, type Editor } from './AdminUI';

export function Meals({ events }: { events: EventSummary[] }) {
  const resource = useAdminData('/api/admin/meals'); const list = rows(record(resource.data).meals);
  const [editor, setEditor] = useState<Editor | null>(null); const [qr, setQr] = useState<{ token: string; image: string } | null>(null);
  const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [passToken, setPassToken] = useState(''); const [busy, setBusy] = useState(false); const [claim, setClaim] = useState<unknown>(null);
  return <section><div className="admin-section-heading"><h2>Food counter &amp; meals</h2><button disabled={!events.length} onClick={() => setEditor({ title: 'Create meal session', path: '/api/admin/meals', fields: [{ name: 'typeOfMeal', label: 'Meal', options: ['breakfast', 'lunch', 'dinner'].map(value => ({ value, label: value })) }, { name: 'date', label: 'Date', type: 'date', required: true }, ...events.map(e => ({ name: `event:${e.id}`, label: e.name, type: 'checkbox' }))], transform: data => { const eventIds = events.filter(e => data[`event:${e.id}`]).map(e => e.id); if (!eventIds.length) throw new Error('Select at least one event.'); return { typeOfMeal: data.typeOfMeal, date: new Date(String(data.date)).toISOString(), eventIds }; } })}>Create meal</button></div>
    <LoadState {...resource} />{resource.error && <p>Meal features require the backend meal schema to be installed. Other admin sections remain available.</p>}
    {error && <p role="alert" className="admin-error">{error}</p>}{notice && <p role="status" className="admin-success">{notice}</p>}
    <form className="admin-card" onSubmit={async e => { e.preventDefault(); setBusy(true); setError(''); setNotice(''); setClaim(null); try { setClaim(await adminRequest('/api/admin/meals/redeem-pass', { passToken: passToken.trim() })); setNotice('Meal pass redeemed successfully.'); setPassToken(''); resource.reload(); } catch (err) { setError(err instanceof Error ? err.message : 'Redemption failed.'); } finally { setBusy(false); } }}>
      <h3>Redeem participant pass</h3><label>Scan with a barcode reader or paste the pass token<input required value={passToken} onChange={e => setPassToken(e.target.value)} placeholder="PASS-…" /></label><button className="primary" disabled={busy}>{busy ? 'Verifying…' : 'Verify and redeem'}</button>{!!claim && <Details value={claim} />}
    </form>
    <Table headings={['Meal', 'Date', 'Eligible events', 'Served', 'Actions']} empty={!list.length}>{list.map(meal => <tr key={text(meal.id)}><td>{text(meal.typeOfMeal)}</td><td>{new Date(String(meal.date)).toLocaleDateString()}</td><td>{rows(meal.events).map(e => text(e.name)).join(', ')}</td><td>{text(meal.scannedCount)}</td><td><div className="admin-actions"><button onClick={async () => { setError(''); try { const result = await adminRequest(`/api/admin/meals/${enc(meal.id)}/qr`); const QRCode = await import('qrcode'); setQr({ token: result.qrToken, image: await QRCode.toDataURL(result.qrToken, { width: 280 }) }); } catch (err) { setError(err instanceof Error ? err.message : 'QR unavailable.'); } }}>Counter QR</button><button onClick={() => setEditor({ title: `Verify participant — ${text(meal.typeOfMeal)}`, path: `/api/admin/meals/${enc(meal.id)}/verify-participant`, fields: [{ name: 'identifier', label: 'Fest ID, email or user ID', required: true }], warning: 'This verifies and redeems the participant’s meal.' })}>Manual verification</button></div></td></tr>)}</Table>
    {qr && <article className="admin-card"><h3>Food counter QR</h3><Image src={qr.image} width={280} height={280} unoptimized alt="Food counter meal QR code" /><p className="break-all">{qr.token}</p><button onClick={async () => { try { await navigator.clipboard.writeText(qr.token); setNotice('Token copied.'); } catch { setError('Clipboard unavailable. Select and copy the displayed token.'); } }}>Copy token</button><button onClick={() => setQr(null)}>Close QR</button></article>}
    {editor && <EditorDialog editor={editor} close={() => setEditor(null)} saved={() => { setNotice('Saved successfully.'); resource.reload(); }} />}
  </section>;
}
